#include <iostream>

int main() {
    int arr[] = {10, 20, 30, 40};
    int size = sizeof(arr) / sizeof(arr[0]);
    int sum = 0;

    for (int i = 0; i < size; i++) {
        arr[i] = arr[i] * 2;
        sum += arr[i];
    }
    std::cout << sum << std::endl;
    std::cout << arr[0] << ' ' << arr[3] << std::endl;
    return 0;
}

#include <iostream>
#include <string>

int main() {
    std::string first = "Hello";
    std::string second = "World";
    std::string phrase = first + " " + second;

    std::cout << phrase << std::endl;
    std::cout << phrase.size() << std::endl;
    std::cout << phrase[0] << phrase[10] << std::endl;

    int pos = phrase.find("World");
    std::cout << pos << ' ' << phrase.substr(0, 5) << std::endl;
    return 0;
}

#include <iostream>
#include <vector>

int main() {
    std::vector<int> v = {5, 10, 15};
    v.push_back(20);
    v.push_back(25);

    int sum = 0;
    for (int value : v) {
        sum += value;
    }
    std::cout << "size: " << v.size() << std::endl;
    std::cout << "sum: " << sum << std::endl;

    v.pop_back();
    std::cout << "first: " << v.front() << " last: " << v.back() << std::endl;
    return 0;
}

#include <iostream>
#include <string>
#include <vector>

struct Student {
    std::string name;
    int course;
    double grade;
};

int main() {
    std::vector<Student> group = {
        {"Anna", 1, 4.5},
        {"Boris", 1, 3.8}
    };

    Student best = group[0];
    if (group[1].grade > best.grade) {
        best = group[1];
    }
    std::cout << "Best: " << best.name << std::endl;

    double sum = group[0].grade + group[1].grade;
    std::cout << "Avg: " << sum / group.size() << std::endl;
    return 0;
}

#include <iostream>

void swap(int& a, int& b) {
    int tmp = a;
    a = b;
    b = tmp;
}

int main() {
    double x = 3.14;
    double* p = &x;
    double& r = x;
    r = 2.71;
    std::cout << x << ' ' << *p << std::endl;

    int a = 1, b = 2;
    swap(a, b);
    std::cout << a << ' ' << b << std::endl;
    return 0;
}
